{ arg out=0, freq=440, amp=0.1, gate=1, modFreqRatio=1.5, modIndex=5;
    var sig, car, mod;
    var env = EnvGen.ar(
        Env.adsr(0.01, 0.1, 0.8, 1.0, curve: -4),
        gate: gate,
        doneAction: 2
    );
    mod = SinOsc.ar(freq * modFreqRatio) * (freq * modIndex);
    car = SinOsc.ar(freq + mod);
    sig = car * amp * env;
    Out.ar(out, sig ! 2);
}
